const commitment = commitments.find(
  (record) => record.kind === "commitment" && record.id === installment.commitmentId,
);
const authority = commitment?.kind === "commitment"
  ? authorities.find((record) => record.id === commitment.appropriationId)
  : undefined;
const plan = commitment?.kind === "commitment"
  ? commitment.installments[installment.installmentIndex]
  : undefined;
const chain = [
  `legislativeMeasures:${measure.id}`,
  ...(authority ? [`publicProgramRecords:${authority.id}`] : []),
  ...(commitment ? [`publicProgramRecords:${commitment.id}`] : []),
  `publicProgramRecords:${installment.id}`,
  ...(flow ? [`resourceFlows:${flow.id}`] : []),
  `resourceTransferOutcomes:${payment.id}`,
].join("; ");
if (effect.effect === "program-payment")
  evidence.push({
    record: chain,
    touched: flow ? JSON.stringify(flow.recipient) : base.jurisdiction,
    before: null,
    after: {
      ...payment.transferredAmount,
      purpose: plan?.purpose ?? null,
      installmentIndex: installment.installmentIndex,
      deliveryLeadDays: commitment?.kind === "commitment" ? commitment.deliveryLeadDays : null,
    },
    detail: "Completed transfer, with its saved plan purpose and full authority/payment chain. Payment does not prove service.",
  });
if (effect.effect === "public-service") {
  if (!commitment || commitment.kind !== "commitment" || !plan) {
    reason = "completed-payment-without-saved-installment-plan";
    continue;
  }
  if (plan.purpose === "maintenance") {
    const outturns = records.filter(
      (record) => record.kind === "capacity-outturn" &&
        record.installmentId === installment.id && record.commitmentId === commitment.id,
    );
    for (const outturn of outturns) {
      if (outturn.kind !== "capacity-outturn" || outturn.restoredUnits === null || outturn.restoredUnits <= 0) continue;
      evidence.push({
        record: `${chain}; publicProgramRecords:${outturn.id}; events:${outturn.eventId}`,
        touched: world.jurisdictions[outturn.jurisdictionId]?.name ?? base.jurisdiction,
        before: outturn.unitsOperational - outturn.restoredUnits,
        after: {
          purpose: plan.purpose,
          restoredUnits: outturn.restoredUnits,
          unitsOperational: outturn.unitsOperational,
          recordedAt: outturn.recordedAt,
          serviceLabel: outturn.serviceLabel ?? null,
          unitLabel: outturn.unitLabel ?? null,
        },
        detail: "Counted maintenance restoration, not operating hours, ridership or actual access. Declared unit costs may be authored.",
      });
    }
    if (outturns.length === 0)
      reason = `completed-maintenance-payment-without-capacity-outturn; installment=${installment.id}; deliveryLeadDays=${commitment.deliveryLeadDays}`;
    else if (!outturns.some((record) => record.kind === "capacity-outturn" && record.restoredUnits !== null && record.restoredUnits > 0))
      reason = `recorded-maintenance-outturn-without-positive-counted-restoration; outturns=${outturns.map((record) => record.id).join(",")}`;
    continue;
  }
  if (plan.purpose !== "operating") {
    reason = `completed-payment-purpose-needs-own-service-adapter: ${plan.purpose}`;
    continue;
  }
  const delivered = world.history.events.filter(
    (event) => event.type === "transit.program-paid-service-hours" &&
      event.involvedEntityIds.includes(measure.id) &&
      event.involvedEntityIds.includes(payment.resourceFlowId),
  );
  for (const event of delivered)
    evidence.push({
      record: `${chain}; events:${event.id}`,
      touched: world.jurisdictions[event.jurisdictionId!]?.name ?? base.jurisdiction,
      before: null,
      after: { purpose: plan.purpose, summary: event.summary },
      detail: "Operating paid-hours record only; actual availability, ridership and travel time are separate.",
    });
  if (delivered.length === 0)
    reason = "completed-operating-payment-without-matching-paid-service-event";
}
